#import <Foundation/Foundation.h>

int digit(int a, int b) {
    int x = a + b;
    int d = 0;
    while (x > 0) {
        d++;
        x /= 10;
    }
    return d;
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        int NUM = 1000;
        int **p = (int **)malloc(NUM * sizeof(int *));
        for (int i = 0; i < NUM; i++) {
            p[i] = (int *)malloc(2 * sizeof(int));
        }

        int i = 0;
        NSString *input = [NSString stringWithContentsOfFile:@"/dev/stdin" encoding:NSUTF8StringEncoding error:nil];
        NSArray *lines = [input componentsSeparatedByString:@"\n"];

        for (NSString *line in lines) {
            if ([line hasPrefix:@"#"]) {
                continue;
            }
            NSArray *values = [line componentsSeparatedByString:@" "];
            if (values.count == 2) {
                p[i][0] = [values[0] intValue];
                p[i][1] = [values[1] intValue];
                i++;
            }
        }

        for (int j = 0; j < i; j++) {
            NSLog(@"%d", digit(p[j][0], p[j][1]));
        }

        for (int j = 0; j < NUM; j++) {
            free(p[j]);
        }
        free(p);
    }
    return 0;
}

